mapper.select:
/*selectSellerMpStDeliveryRecordList*/
SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS WMS_NAME , DECODE(A.RECV_FLAG,'A','권고발주' ,'B','송장생성' ,'C','입고완료') AS RECV_FLAG_NAME /* 구분 */ , A.VPO_NO /* 발주송장번호 */ , A.BUYER_ITEM_NO /* 자재코드 */ , A.DESCRIPTION /* 품명 */ , A.SPECIFICATION /* 규격 */ , A.UNIT_MEASURE /* 단위 */ , A.GR_QTY /* 입고수량 */ , A.VGR_DATE /* 입고일자 */ , A.ITEM_QTY /* 발주수량 */ , A.VPO_DATE /* 발주일자 */ , A.IV_QTY /* 송장수량 */ , A.VIV_DATE /* 송장일자 */ , A.VPO_REMARK /* 비고 */ , A.BUYER , A.VPO_SEQ , A.RECV_FLAG FROM EDIVPODT A WHERE A.AGENT = #{st_com_code} AND A.STATUS <> 'D'
AND A.RECV_FLAG = #{st_status_ing}
AND A.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.VGR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.VPO_DATE BETWEEN #{st_from_date} AND #{st_to_date}
ORDER BY 2,4
